"\n"
"/* Same distance as rvn_sd_round_box, and the direction pointing out of the shape (for the rim of glass). */\n"
"float sd_round_box_normal(float2 p, float2 half_size, float4 radii, thread float2& normal) {\n"
"\tfloat radius = p.x < 0.0 ? (p.y < 0.0 ? radii.x : radii.w) : (p.y < 0.0 ? radii.y : radii.z);\n"
"\tradius = min(radius, min(half_size.x, half_size.y));\n"
"\tfloat2 side = float2(p.x < 0.0 ? -1.0 : 1.0, p.y < 0.0 ? -1.0 : 1.0);\n"
"\tfloat2 q = abs(p) - half_size + radius;\n"
"\tfloat corner = length(max(q, 0.0));\n"
"\tif (q.x > 0.0 && q.y > 0.0) normal = side * (q / max(corner, 1e-4));\n"
"\telse normal = q.x > q.y ? float2(side.x, 0.0) : float2(0.0, side.y);\n"
"\treturn min(max(q.x, q.y), 0.0) + corner - radius;\n"
"}\n"
"\n"
"/*\n"
" * Dispersion: glass bends violet more than red, so what its rim shows is\n"
" * split into a thin rainbow. Seven wavelengths, from red (bent least) to\n"
" * violet (bent most), each read where it lands; their weights add up to\n"
" * white, so a plain backdrop stays plain and the colors only show where\n"
" * the backdrop changes: on edges, text, shapes passing under the rim.\n"
" */\n"
"constant float3 SPECTRUM[7] = {\n"
"\tfloat3(0.2788, 0.0146, 0.0000),\n"
"\tfloat3(0.3163, 0.0831, 0.0011),\n"
"\tfloat3(0.2022, 0.2356, 0.0133),\n"
"\tfloat3(0.0728, 0.3333, 0.0812),\n"
"\tfloat3(0.0165, 0.2356, 0.2467),\n"
"\tfloat3(0.0325, 0.0831, 0.3742),\n"
"\tfloat3(0.0810, 0.0146, 0.2834)\n"
"};\n"
"\n"
"/* What lies behind p seen through a rim that bends it by `shift` pixels, each wavelength by `spread` more or less. */\n"
"float3 dispersed(texture2d<float> source, float2 p, float2 shift, float spread, float2 inv_size) {\n"
"\tfloat3 sum = float3(0.0);\n"
"\tfor (int i = 0; i < 7; i++) {\n"
"\t\tfloat k = float(i) / 3.0 - 1.0;\n"
"\t\tsum += source.sample(rvn_linear, (p + shift * (1.0 + spread * k)) * inv_size, level(0.0)).rgb * SPECTRUM[i];\n"
"\t}\n"
"\treturn sum;\n"
"}\n"
"\n"
"/*\n"
" * Glass: a thick, rounded slab. Its flat middle shows the backdrop, more or\n"
" * less frosted; its curved rim bends it like a lens, splits the colors a\n"
" * little, and catches the light.\n"
" */\n"
"float4 glass(thread const RvnVaryings& in, float2 p, float d, float2 normal,\n"
"\ttexture2d<float> u_backdrop, texture2d<float> u_backdrop_blur) {\n"
"\tfloat frost = in.params.x;\n"
"\tfloat refraction = in.params.y;\n"
"\tfloat bevel = max(in.border_width, 1.0);\n"
"\n"
"\t/* 1 on the edge, 0 where the rim meets the flat part; the cube keeps the middle undistorted */\n"
"\tfloat t = clamp(1.0 + d / bevel, 0.0, 1.0);\n"
"\tfloat bend = t * t * t;\n"
"\n"
"\t/* the rim shows what lies further inside: content appears pulled toward the edge */\n"
"\tfloat2 shift = -normal * bend * refraction;\n"
"\tfloat2 uv = (p + shift) * in.inv_size;\n"
"\tfloat4 middle = u_backdrop.sample(rvn_linear, uv, level(0.0));\n"
"\tfloat4 wide = u_backdrop_blur.sample(rvn_linear, uv, level(0.0));\n"
"\tfloat3 sharp = middle.rgb;\n"
"\tfloat3 blurred = wide.rgb;\n"
"\t/* the rim splits the colors (the flat middle reads one sample); a frosted\n"
"\t * backdrop is softer, so it is spread a little further to keep its rainbow */\n"
"\tif (bend > 0.002 && refraction > 0.0) {\n"
"\t\tif (frost < 0.999) sharp = dispersed(u_backdrop, p, shift, 0.50, in.inv_size);\n"
"\t\tif (frost > 0.001) blurred = dispersed(u_backdrop_blur, p, shift, 0.70, in.inv_size);\n"
"\t}\n"
"\tfloat3 color = mix(sharp, blurred, frost);\n"
"\t/* how much of the window there is behind: less than 1 where it lets the screen show (see-through windows) */\n"
"\tfloat behind = mix(middle.a, wide.a, frost);\n"
"\n"
"\t/* vivid colors survive the frosting */\n"
"\tfloat luma = dot(color, float3(0.2126, 0.7152, 0.0722));\n"
"\tcolor = max(mix(float3(luma), color, in.params.z), 0.0);\n"
"\n"
"\t/* tint (in.color is premultiplied) */\n"
"\tcolor = color * (1.0 - in.color.a) + in.color.rgb;\n"
"\n"
"\t/* light comes from the top left: a thin bright line on the rim, strongest\n"
"\t * where it faces the light, with an echo on the opposite side */\n"
"\tconst float2 light = float2(-0.5547, -0.8321);\n"
"\tfloat facing = dot(normal, light);\n"
"\tfloat lit = 0.22 + (facing > 0.0 ? pow(facing, 1.5) : 0.5 * pow(-facing, 1.5));\n"
"\tfloat line_width = clamp(bevel * 0.12, 1.0, 2.5);\n"
"\tfloat line = clamp(1.0 + d / line_width, 0.0, 1.0);\n"
"\tcolor += in.border_color.rgb * (line * line * lit + bend * 0.10);\n"
"\n"
"\t/* the rim is a curved mirror too: it reflects what lies around the slab,\n"
"\t * so colors that come close to the glass show on its edge before they\n"
"\t * pass under it */\n"
"\tfloat3 around = u_backdrop_blur.sample(rvn_linear, (p + normal * (bevel * 1.5 + 6.0)) * in.inv_size, level(0.0)).rgb;\n"
"\tcolor += around * (1.0 - color) * bend * 0.45 * in.border_color.a;\n"
"\n"
"\t/* a slab is a little brighter at the top than at the bottom */\n"
"\tfloat height = max(in.rect.w - in.rect.y, 1.0);\n"
"\tcolor += in.border_color.a * 0.07 * (0.5 - (p.y - in.rect.y) / height);\n"
"\n"
"\tcolor += in.params.w;\n"
"\tfloat opacity = float((in.flags >> 8) & 255u) / 255.0;\n"
"\t/* over nothing, glass is only its tint and its light: the screen shows through the rest */\n"
"\tfloat alpha = clamp(1.0 - (1.0 - in.color.a) * (1.0 - behind) + in.border_color.a * line * line * lit, 0.0, 1.0);\n"
"\treturn float4(clamp(color, 0.0, 1.0), alpha) * opacity;\n"
"}\n"
"\n"
"/* Fine grain, the same in every frame: what tells frosted glass from a blurred picture. */\n"
"float grain(float2 p) {\n"
"\treturn fract(sin(dot(floor(p), float2(12.9898, 78.233))) * 43758.5453) - 0.5;\n"
"}\n"
"\n"
"/*\n"
" * Blur: what is behind, out of focus by a radius in pixels (in.params.x),\n"
" * with its colors strengthened or weakened (z), a grain (y) and a tint.\n"
" * Small radii are worked out here from the half-size copy of the frame, a\n"
" * ring of samples around the pixel; large ones come from the copy that is\n"
" * already blurred wide, pushed further when the radius asks for more.\n"
" */\n"
"float4 blur(thread const RvnVaryings& in, float2 p, float d, float2 normal, float band,\n"
"\ttexture2d<float> u_backdrop, texture2d<float> u_backdrop_blur) {\n"
"\tconst float WIDE = 22.0;\n"
"\tfloat radius = max(in.params.x, 0.0);\n"
"\tfloat2 uv = p * in.inv_size;\n"
"\tfloat4 color;\n"
"\tif (radius < 0.75) {\n"
"\t\tcolor = u_backdrop.sample(rvn_linear, uv, level(0.0));\n"
"\t} else {\n"
"\t\t/* sixteen samples on a spiral: the golden angle spreads them evenly over the disc */\n"
"\t\tfloat4 near = float4(0.0);\n"
"\t\tfloat reach = min(radius, WIDE);\n"
"\t\tfor (int i = 0; i < 16; i++) {\n"
"\t\t\tfloat t = (float(i) + 0.5) / 16.0;\n"
"\t\t\tfloat angle = float(i) * 2.39996323;\n"
"\t\t\tfloat2 offset = float2(cos(angle), sin(angle)) * sqrt(t) * reach;\n"
"\t\t\tnear += u_backdrop.sample(rvn_linear, uv + offset * in.inv_size, level(0.0));\n"
"\t\t}\n"
"\t\tnear /= 16.0;\n"
"\t\tfloat4 far = u_backdrop_blur.sample(rvn_linear, uv, level(0.0));\n"
"\t\tif (radius > WIDE) {\n"
"\t\t\t/* wider than the wide copy: a ring of it, as far as the radius goes past */\n"
"\t\t\tfloat extra = radius - WIDE;\n"
"\t\t\tfloat4 ring = float4(0.0);\n"
"\t\t\tfor (int i = 0; i < 8; i++) {\n"
"\t\t\t\tfloat angle = float(i) * 0.78539816;\n"
"\t\t\t\tring += u_backdrop_blur.sample(rvn_linear, uv + float2(cos(angle), sin(angle)) * extra * in.inv_size, level(0.0));\n"
"\t\t\t}\n"
"\t\t\tfar = mix(far, ring / 8.0, 0.75);\n"
"\t\t}\n"
"\t\tcolor = mix(near, far, smoothstep(WIDE * 0.45, WIDE, radius));\n"
"\t}\n"
"\t/* its edge is the edge of a pane: a narrow band that bends what is behind\n"
"\t * toward the inside and splits it into a faint rainbow, as glass does */\n"
"\tfloat t = clamp(1.0 + d / band, 0.0, 1.0);\n"
"\tfloat bend = t * t * t;\n"
"\tif (bend > 0.002) {\n"
"\t\t/* (read from the sharp frame: in the blurred one, the colors would have nothing left to split) */\n"
"\t\tfloat3 rim = dispersed(u_backdrop, p, -normal * bend * band * 1.2, 0.80, in.inv_size);\n"
"\t\tcolor.rgb = mix(color.rgb, rim * color.a, bend * 0.55);\n"
"\t}\n"
"\tfloat luma = dot(color.rgb, float3(0.2126, 0.7152, 0.0722));\n"
"\tcolor.rgb = max(mix(float3(luma), color.rgb, in.params.z), 0.0);\n"
"\tcolor.rgb += grain(p) * in.params.y * 0.04 * color.a;\n"
"\t/* tint (premultiplied), then a little light or shade over the whole */\n"
"\tcolor = color * (1.0 - in.color.a) + in.color;\n"
"\tcolor.rgb += in.params.w * color.a;\n"
"\tfloat opacity = float((in.flags >> 8) & 255u) / 255.0;\n"
"\treturn clamp(color, 0.0, 1.0) * opacity;\n"
"}\n"
"\n"
"float sd_segment(float2 p, float2 a, float2 b) {\n"
"\tfloat2 pa = p - a;\n"
"\tfloat2 ba = b - a;\n"
"\tfloat h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-6), 0.0, 1.0);\n"
"\treturn length(pa - ba * h);\n"
"}\n"
"\n"
"/* Works for both windings. */\n"
"float sd_triangle(float2 p, float2 p0, float2 p1, float2 p2) {\n"
"\tfloat2 e0 = p1 - p0, e1 = p2 - p1, e2 = p0 - p2;\n"
"\tfloat2 v0 = p - p0, v1 = p - p1, v2 = p - p2;\n"
"\tfloat2 pq0 = v0 - e0 * clamp(dot(v0, e0) / max(dot(e0, e0), 1e-6), 0.0, 1.0);\n"
"\tfloat2 pq1 = v1 - e1 * clamp(dot(v1, e1) / max(dot(e1, e1), 1e-6), 0.0, 1.0);\n"
"\tfloat2 pq2 = v2 - e2 * clamp(dot(v2, e2) / max(dot(e2, e2), 1e-6), 0.0, 1.0);\n"
"\tfloat s = sign(e0.x * e2.y - e0.y * e2.x);\n"
"\tfloat2 d = min(min(\n"
"\t\tfloat2(dot(pq0, pq0), s * (v0.x * e0.y - v0.y * e0.x)),\n"
"\t\tfloat2(dot(pq1, pq1), s * (v1.x * e1.y - v1.y * e1.x))),\n"
"\t\tfloat2(dot(pq2, pq2), s * (v2.x * e2.y - v2.y * e2.x)));\n"
"\treturn -sqrt(d.x) * sign(d.y);\n"
"}\n"
"\n"
"fragment float4 rvn_ui_fragment(RvnVaryings in [[stage_in]],\n"
"\ttexture2d<float> u_texture [[texture(0)]], sampler u_sampler [[sampler(0)]],\n"
"\ttexture2d<float> u_backdrop [[texture(1)]], texture2d<float> u_backdrop_blur [[texture(2)]]) {\n"
"\t/* the derivatives of the coordinates are taken while the whole quad runs\n"
"\t * (before the discard and the branches): they choose the mip level of the\n"
"\t * textures that have mipmaps; the samplers of the others read level 0 only */\n"
"\tfloat2 uv_dx = dfdx(in.uv), uv_dy = dfdy(in.uv);\n"
"\tfloat2 p = in.position.xy;\n"
"\tif (p.x < in.clip.x || p.y < in.clip.y || p.x >= in.clip.z || p.y >= in.clip.w) {\n"
"\t\tdiscard_fragment();\n"
"\t\treturn float4(0.0);\n"
"\t}\n"
"\n"
"\tuint kind = in.flags & RVN_PRIM_MASK;\n"
"\tfloat4 color = in.color;\n"
"\tif ((in.flags & RVN_FLAG_TEXTURED) != 0u) {\n"
"\t\tfloat4 texel = u_texture.sample(u_sampler, in.uv, gradient2d(uv_dx, uv_dy));\n"
"\t\t/* textures are straight alpha, in.color is already premultiplied */\n"
"\t\tcolor *= float4(texel.rgb * texel.a, texel.a);\n"
"\t}\n"
"\n"
"\tfloat coverage = 1.0;\n"
"\tif (kind == RVN_PRIM_RECT) {\n"
"\t\tfloat2 half_size = (in.rect.zw - in.rect.xy) * 0.5;\n"
"\t\tfloat d = rvn_sd_round_box(p - (in.rect.xy + half_size), half_size, in.radii);\n"
"\t\tcoverage = clamp(0.5 - d, 0.0, 1.0);\n"
"\t\tif (in.border_width > 0.0) {\n"
"\t\t\tfloat inside = clamp(0.5 - (d + in.border_width), 0.0, 1.0);\n"
"\t\t\tcolor = mix(in.border_color, color, inside);\n"
"\t\t}\n"
"\t} else if (kind == RVN_PRIM_SHADOW) {\n"
"\t\tfloat2 half_size = (in.rect.zw - in.rect.xy) * 0.5;\n"
"\t\tfloat d = rvn_sd_round_box(p - (in.rect.xy + half_size), half_size, in.radii);\n"
"\t\tfloat blur = max(in.border_width, 0.5);\n"
"\t\tcoverage = 1.0 - smoothstep(-blur, blur, d);\n"
"\t} else if (kind == RVN_PRIM_LINE) {\n"
"\t\tfloat d = sd_segment(p, in.rect.xy, in.rect.zw) - in.radii.x * 0.5;\n"
"\t\tcoverage = clamp(0.5 - d, 0.0, 1.0);\n"
"\t} else if (kind == RVN_PRIM_TRIANGLE) {\n"
"\t\tfloat d = sd_triangle(p, in.rect.xy, in.rect.zw, in.radii.xy);\n"
"\t\tcoverage = clamp(0.5 - d, 0.0, 1.0);\n"
"\t} else if (kind == RVN_PRIM_CURVE) {\n"
"\t\t/* a cubic curve, followed as a chain of short segments: the nearest one gives the distance and how far along it is */\n"
"\t\tfloat2 a = in.rect.xy, b = in.radii.xy, c = in.radii.zw, e = in.rect.zw;\n"
"\t\tfloat2 from = a;\n"
"\t\tfloat nearest = 1e20, along = 0.0;\n"
"\t\tfor (int i = 1; i <= 24; i++) {\n"
"\t\t\tfloat t = float(i) / 24.0;\n"
"\t\t\tfloat u = 1.0 - t;\n"
"\t\t\tfloat2 to = u * u * u * a + 3.0 * u * u * t * b + 3.0 * u * t * t * c + t * t * t * e;\n"
"\t\t\tfloat2 pa = p - from, ba = to - from;\n"
"\t\t\tfloat h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-6), 0.0, 1.0);\n"
"\t\t\tfloat2 away = pa - ba * h;\n"
"\t\t\tfloat d2 = dot(away, away);\n"
"\t\t\tif (d2 < nearest) {\n"
"\t\t\t\tnearest = d2;\n"
"\t\t\t\talong = (float(i - 1) + h) / 24.0;\n"
"\t\t\t}\n"
"\t\t\tfrom = to;\n"
"\t\t}\n"
"\t\tfloat d = sqrt(nearest) - in.border_width * 0.5;\n"
"\t\tfloat stroke = clamp(0.5 - d, 0.0, 1.0);\n"
"\t\tfloat pulse = 0.0;\n"
"\t\tcolor = mix(in.color, in.border_color, along);\n"
"\t\tfloat bright = float((in.flags >> 8) & 255u) / 255.0;\n"
"\t\tif (in.params.w > 0.0 && bright > 0.0) {\n"
"\t\t\t/* pulses of light that run from one end to the other */\n"
"\t\t\tfloat f = fract(along * in.params.w - in.params.z) - 0.5;\n"
"\t\t\tpulse = exp(-f * f * 80.0) * bright;\n"
"\t\t\tcolor.rgb = mix(color.rgb, float3(color.a), pulse * 0.6);\n"
"\t\t}\n"
"\t\tfloat halo = 0.0;\n"
"\t\tif (in.params.x > 0.0) {\n"
"\t\t\thalo = 1.0 - smoothstep(0.0, in.params.x, max(d, 0.0));\n"
"\t\t\thalo = halo * halo * in.params.y * (1.0 + pulse * 0.8);\n"
"\t\t}\n"
"\t\tcoverage = stroke + (1.0 - stroke) * min(halo, 1.0);\n"
"\t} else if (kind == RVN_PRIM_GLASS) {\n"
"\t\tfloat2 half_size = (in.rect.zw - in.rect.xy) * 0.5;\n"
"\t\tfloat2 normal;\n"
"\t\tfloat d = sd_round_box_normal(p - (in.rect.xy + half_size), half_size, in.radii, normal);\n"
"\t\tcoverage = clamp(0.5 - d, 0.0, 1.0);\n"
"\t\tcolor = glass(in, p, d, normal, u_backdrop, u_backdrop_blur);\n"
"\t} else if (kind == RVN_PRIM_BLUR) {\n"
"\t\tfloat2 half_size = (in.rect.zw - in.rect.xy) * 0.5;\n"
"\t\tfloat2 normal;\n"
"\t\tfloat d = sd_round_box_normal(p - (in.rect.xy + half_size), half_size, in.radii, normal);\n"
"\t\tcoverage = clamp(0.5 - d, 0.0, 1.0);\n"
"\t\tcolor = blur(in, p, d, normal, clamp(min(half_size.x, half_size.y) * 0.12, 3.0, 12.0), u_backdrop, u_backdrop_blur);\n"
"\t\tif (in.border_width > 0.0) {\n"
"\t\t\t/* a hairline around it, over the blur */\n"
"\t\t\tfloat inside = clamp(0.5 - (d + in.border_width), 0.0, 1.0);\n"
"\t\t\tcolor = mix(in.border_color + color * (1.0 - in.border_color.a), color, inside);\n"
"\t\t}\n"
"\t}\n"
"\n"
"\treturn color * coverage;\n"
"}\n"
"\n"
"/*\n"
" * What a backend without the shader of an R_DRAW_SHADER command may draw\n"
" * (raven_backend.h): the rounded rectangle of the instance filled with its\n"
" * color. Used for the effects of the application (SPIR-V, which Metal does\n"
" * not read) and for a built-in effect whose library did not compile. Same\n"
" * clip test and coverage as the RECT branch above, no outline, times the\n"
" * opacity of bits 8..15 of the flags.\n"
" */\n"
"fragment float4 rvn_shader_fallback_fragment(RvnVaryings in [[stage_in]]) {\n"
"\tfloat2 p = in.position.xy;\n"
"\tif (p.x < in.clip.x || p.y < in.clip.y || p.x >= in.clip.z || p.y >= in.clip.w) {\n"
"\t\tdiscard_fragment();\n"
"\t\treturn float4(0.0);\n"
"\t}\n"
"\tfloat2 half_size = (in.rect.zw - in.rect.xy) * 0.5;\n"
"\tfloat d = rvn_sd_round_box(p - (in.rect.xy + half_size), half_size, in.radii);\n"
"\tfloat coverage = clamp(0.5 - d, 0.0, 1.0);\n"
"\tfloat opacity = float((in.flags >> 8) & 255u) / 255.0;\n"
"\treturn in.color * (coverage * opacity);\n"
"}\n";

/* shaders/blur.metal */
static const char rvn_mtl_blur_source[] =
"/*\n"
" * Raven - blur.metal\n"
" * The passes that build the backdrop of the glass primitives:\n"
" * src/render/vulkan/shaders/blur.vert and blur.frag in the Metal Shading\n"
" * Language. Compiled after common.metal.\n"
" *\n"
" * A wide blur is built cheaply with the \"dual filtering\" scheme: the frame is\n"
" * reduced by half a few times (mode 0), then enlarged back (mode 1). Every\n"
" * pass reads a handful of bilinear samples, so the cost stays small whatever\n"
" * the blur radius. Mode 2 is a plain copy.\n"
" */\n"
"\n"
"/* Full-screen triangle, no vertex buffer. Metal's clip space points up: the\n"
" * first row of the source (uv.y = 0) is drawn at the top of the target. */\n"
"vertex RvnBlurVaryings rvn_blur_vertex(uint vid [[vertex_id]]) {\n"
"\tRvnBlurVaryings out;\n"
"\tfloat2 corner = float2(float((vid << 1) & 2u), float(vid & 2u));\n"
"\tout.uv = corner;                                                       /* (0, 0) = top left of the source */\n"
"\tout.position = float4(corner.x * 2.0 - 1.0, 1.0 - corner.y * 2.0, 0.0, 1.0);\n"
"\treturn out;\n"
"}\n"
"\n"
"fragment float4 rvn_blur_fragment(RvnBlurVaryings in [[stage_in]],\n"
"\ttexture2d<float> source [[texture(0)]], constant RvnBlurUniforms& u [[buffer(0)]]) {\n"
"\tfloat2 uv = in.uv;\n"
"\tif (u.mode == 0) {\n"
"\t\t/* reduce: the center and the four diagonals */\n"
"\t\tfloat4 sum = source.sample(rvn_linear, uv, level(0.0)) * 4.0;\n"
"\t\tsum += source.sample(rvn_linear, uv + float2(-u.step.x, -u.step.y), level(0.0));\n"
"\t\tsum += source.sample(rvn_linear, uv + float2( u.step.x, -u.step.y), level(0.0));\n"
"\t\tsum += source.sample(rvn_linear, uv + float2(-u.step.x,  u.step.y), level(0.0));\n"
"\t\tsum += source.sample(rvn_linear, uv + float2( u.step.x,  u.step.y), level(0.0));\n"
"\t\treturn sum / 8.0;\n"
"\t} else if (u.mode == 1) {\n"
"\t\t/* enlarge: a ring of eight samples */\n"
"\t\tfloat4 sum = source.sample(rvn_linear, uv + float2(-u.step.x * 2.0, 0.0), level(0.0));\n"
"\t\tsum += source.sample(rvn_linear, uv + float2( u.step.x * 2.0, 0.0), level(0.0));\n"
"\t\tsum += source.sample(rvn_linear, uv + float2(0.0, -u.step.y * 2.0), level(0.0));\n"
"\t\tsum += source.sample(rvn_linear, uv + float2(0.0,  u.step.y * 2.0), level(0.0));\n"
"\t\tsum += source.sample(rvn_linear, uv + float2(-u.step.x,  u.step.y), level(0.0)) * 2.0;\n"
"\t\tsum += source.sample(rvn_linear, uv + float2( u.step.x,  u.step.y), level(0.0)) * 2.0;\n"
"\t\tsum += source.sample(rvn_linear, uv + float2(-u.step.x, -u.step.y), level(0.0)) * 2.0;\n"
"\t\tsum += source.sample(rvn_linear, uv + float2( u.step.x, -u.step.y), level(0.0)) * 2.0;\n"
"\t\treturn sum / 12.0;\n"
"\t} else {\n"
"\t\treturn source.sample(rvn_linear, uv, level(0.0));\n"
"\t}\n"
"}\n";

/* shaders/effect.metal */
static const char rvn_mtl_effect_source[] =
"/*\n"
" * Raven - effect.metal\n"
" * What Raven does around an effect on the Metal backend: the MSL twin of\n"
" * include/raven/shaders/raven_effect.glsl, which stays the reference (the\n"
" * comments and names are kept so that the two can be read side by side).\n"
" *\n"
" * The library of an effect is common.metal + this file + effects/<name>.metal.\n"
" * The file of the effect defines one function:\n"
" *\n"
" *     float4 raven_effect(RAVEN_EFFECT_ARGS) {\n"
" *         return mix(fx.color, fx.color2, fx.uv.x);   // straight alpha, 0..1\n"
" *     }\n"
" *\n"
" * Raven calls it for every pixel of the rectangle. The rounded corners, the\n"
" * anti-aliased edge, the clipping of the widget and its opacity are applied\n"
" * to what it returns: the effect only says what color the pixel is.\n"
" */\n"
"\n"
"/* ---- what the effect receives ---- */\n"
"\n"
"struct RavenEffect {\n"
"\t/** Where the pixel is in the rectangle: (0, 0) top left .. (1, 1) bottom right. */\n"
"\tfloat2 uv;\n"
"\t/** The same in pixels, from the top left corner of the rectangle. */\n"
"\tfloat2 pixel;\n"
"\t/** Size of the rectangle, in pixels. */\n"
"\tfloat2 size;\n"
"\t/** Where the pixel is in the window, in pixels (for raven_backdrop). */\n"
"\tfloat2 screen;\n"
"\t/** Distance to the edge of the rounded rectangle, in pixels: negative inside, 0 on the edge. */\n"
"\tfloat edge;\n"
"\t/** Seconds: grows while the effect is animated. */\n"
"\tfloat time;\n"
"\t/**\n"
"\t * Where the pointer is, in pixels from the top left corner of the\n"
"\t * rectangle, like `pixel` (it may be outside the rectangle). Far away\n"
"\t * (below -1e5) when the pointer is not over the window, or when the\n"
"\t * effect is told not to follow it (RShaderLook::pointer, EffectPointer).\n"
"\t */\n"
"\tfloat2 pointer;\n"
"\t/** How much the pointer is over the widget, 0..1: eased, it rises and falls in a fraction of a second. */\n"
"\tfloat hover;\n"
"\t/** How much the widget is pressed, 0..1 (eased). */\n"
"\tfloat press;\n"
"\t/** The two colors of the look, straight alpha. */\n"
"\tfloat4 color;\n"
"\tfloat4 color2;\n"
"\t/** The four parameters of the look. */\n"
"\tfloat4 params;\n"
"};\n"
"\n"
"/*\n"
" * MSL functions cannot see the bindings of the entry point: they are passed\n"
" * to raven_effect, and the macros below read them by these names.\n"
" */\n"
"#define RAVEN_EFFECT_ARGS RavenEffect fx, texture2d<float> rvn_texture, sampler rvn_texture_sampler, \\\n"
"\ttexture2d<float> rvn_backdrop, texture2d<float> rvn_backdrop_blur, float2 rvn_inv_size\n"
"\n"
"/** The texture of the look (RShaderLook::texture), at uv 0..1. White when there is none. */\n"
"#define raven_texture(uv)           rvn_texture.sample(rvn_texture_sampler, (uv))\n"
"/**\n"
" * What was drawn behind the rectangle, at a position of the window in\n"
" * pixels: sharp, or blurred. Only for a shader created with\n"
" * R_SHADER_BACKDROP (EffectBackdrop=\"true\"); white otherwise.\n"
" */\n"
"#define raven_backdrop(screen)      rvn_backdrop.sample(rvn_linear, (screen) * rvn_inv_size, level(0.0))\n"
"#define raven_backdrop_blur(screen) rvn_backdrop_blur.sample(rvn_linear, (screen) * rvn_inv_size, level(0.0))\n"
"\n"
"/** The effect: the color of the pixel, straight alpha (not premultiplied). Defined by the file of the effect. */\n"
"float4 raven_effect(RAVEN_EFFECT_ARGS);\n"
"\n"
"/* ---- helpers ---- */\n"
"\n"
"constant float RAVEN_PI = 3.14159265358979;\n"
"constant float RAVEN_TAU = 6.28318530717959;\n"
"\n"
"/** A number in 0..1 that looks random, the same for the same point. */\n"
"float raven_hash(float2 p) {\n"
"\tp = fract(p * float2(123.34, 456.21));\n"
"\tp += dot(p, p + 45.32);\n"
"\treturn fract(p.x * p.y);\n"
"}\n"
"\n"
"/** Smooth noise in 0..1. */\n"
"float raven_noise(float2 p) {\n"
"\tfloat2 i = floor(p);\n"
"\tfloat2 f = fract(p);\n"
"\tfloat2 u = f * f * (3.0 - 2.0 * f);\n"
"\treturn mix(mix(raven_hash(i), raven_hash(i + float2(1.0, 0.0)), u.x),\n"
"\t\tmix(raven_hash(i + float2(0.0, 1.0)), raven_hash(i + float2(1.0, 1.0)), u.x), u.y);\n"
"}\n"
"\n"
"/** Noise of noises (fractal Brownian motion), in 0..1. */\n"
"float raven_fbm(float2 p) {\n"
"\tfloat sum = 0.0, amplitude = 0.5;\n"
"\tfor (int i = 0; i < 5; i++) {\n"
"\t\tsum += amplitude * raven_noise(p);\n"
"\t\tp = p * 2.03 + float2(17.1, 9.2);\n"
"\t\tamplitude *= 0.5;\n"
"\t}\n"
"\treturn sum;\n"
"}\n"
"\n"
"/** Hue (0..1), saturation, value -> RGB. */\n"
"float3 raven_hsv(float3 c) {\n"
"\tfloat3 rgb = clamp(abs(rvn_mod(c.x * 6.0 + float3(0.0, 4.0, 2.0), float3(6.0)) - 3.0) - 1.0, 0.0, 1.0);\n"
"\treturn c.z * mix(float3(1.0), rgb, c.y);\n"
"}\n"
"\n"
"/** R_TRUE when the effect knows where the pointer is (it is over the window, and the effect follows it). */\n"
"bool raven_has_pointer(RavenEffect fx) {\n"
"\treturn fx.pointer.x > -1e5;\n"
"}\n"
"\n"
"/** Signed distance to a rounded box centered on the origin (radii: top-left, top-right, bottom-right, bottom-left). */\n"
"float raven_sd_round_box(float2 p, float2 half_size, float4 radii) {\n"
"\treturn rvn_sd_round_box(p, half_size, radii);\n"
"}\n"
"\n"
"/* ---- what Raven does around the effect ---- */\n"
"\n"
"fragment float4 rvn_effect_fragment(RvnVaryings in [[stage_in]],\n"
"\ttexture2d<float> rvn_texture [[texture(0)]], sampler rvn_texture_sampler [[sampler(0)]],\n"
"\ttexture2d<float> rvn_backdrop [[texture(1)]], texture2d<float> rvn_backdrop_blur [[texture(2)]]) {\n"
"\tfloat2 p = in.position.xy;\n"
"\tif (p.x < in.clip.x || p.y < in.clip.y || p.x >= in.clip.z || p.y >= in.clip.w) {\n"
"\t\tdiscard_fragment();\n"
"\t\treturn float4(0.0);\n"
"\t}\n"
"\tfloat2 size = max(in.rect.zw - in.rect.xy, float2(1.0));\n"
"\tfloat2 center = (in.rect.xy + in.rect.zw) * 0.5;\n"
"\tfloat d = rvn_sd_round_box(p - center, size * 0.5, in.radii);\n"
"\tfloat coverage = clamp(0.5 - d, 0.0, 1.0);\n"
"\tif (coverage <= 0.0) {\n"
"\t\tdiscard_fragment();\n"
"\t\treturn float4(0.0);\n"
"\t}\n"
"\n"
"\tRavenEffect fx;\n"
"\tfx.pixel = p - in.rect.xy;\n"
"\tfx.uv = fx.pixel / size;\n"
"\tfx.size = size;\n"
"\tfx.screen = p;\n"
"\tfx.edge = d;\n"
"\tfx.time = in.border_width;\n"
"\tfx.pointer = in.pointer.xy - in.rect.xy;\n"
"\tfx.hover = in.pointer.z;\n"
"\tfx.press = in.pointer.w;\n"
"\t/* (the vertex function premultiplies the colors: the effect gets them straight) */\n"
"\tfx.color = in.color.a > 0.0 ? float4(in.color.rgb / in.color.a, in.color.a) : float4(0.0);\n"
"\tfx.color2 = in.border_color.a > 0.0 ? float4(in.border_color.rgb / in.border_color.a, in.border_color.a) : float4(0.0);\n"
"\tfx.params = in.params;\n"
"\n"
"\tfloat4 color = raven_effect(fx, rvn_texture, rvn_texture_sampler, rvn_backdrop, rvn_backdrop_blur, in.inv_size);\n"
"\tcolor = clamp(color, float4(0.0), float4(1.0));\n"
"\tfloat opacity = float((in.flags >> 8) & 255u) / 255.0;\n"
"\treturn float4(color.rgb * color.a, color.a) * (coverage * opacity);\n"
"}\n";

/* shaders/effects/aurora.metal */
static const char rvn_mtl_effect_aurora_source[] =
"/* Aurora: curtains of light drifting in a night sky.\n"
" * color, color2: the colors of the lights (color low, color2 high). params: speed, scale, intensity.\n"
" * The pointer: the curtains lean toward it and light up around it; a press makes them flare.\n"
" * (MSL twin of src/render/vulkan/shaders/effects/aurora.frag) */\n"
"float4 raven_effect(RAVEN_EFFECT_ARGS) {\n"
"\tfloat speed = fx.params.x, scale = max(fx.params.y, 0.05), intensity = fx.params.z;\n"
"\tfloat aspect = fx.size.x / max(fx.size.y, 1.0);\n"
"\tfloat x = fx.uv.x * aspect * scale;\n"
"\tfloat t = fx.time * 0.08 * speed;\n"
"\n"
"\t/* the night: almost black, a little of the two colors */\n"
"\tfloat3 sky = mix(float3(0.015, 0.02, 0.05), mix(fx.color.rgb, fx.color2.rgb, 0.7) * 0.08, 1.0 - fx.uv.y);\n"
"\tfloat3 light = float3(0.0);\n"
"\t/* how close the pointer is (across mostly: the curtains hang), and where it is */\n"
"\tfloat2 m = fx.pointer / max(fx.size, float2(1.0));\n"
"\tfloat across = (fx.uv.x - m.x) * aspect * 2.2;\n"
"\tfloat near = raven_has_pointer(fx) ? fx.hover * exp(-across * across) : 0.0;\n"
"\tfor (int i = 0; i < 3; i++) {\n"
"\t\tfloat k = float(i);\n"
"\t\t/* the lower edge of a curtain: a line that waves slowly */\n"
"\t\tfloat line = 0.62 - k * 0.13\n"
"\t\t\t+ 0.07 * sin(x * (2.1 + k * 0.7) + t * (3.0 + k) + k * 1.7)\n"
"\t\t\t+ 0.10 * (raven_fbm(float2(x * 1.1 + t * (1.2 + k * 0.4), k * 4.3)) - 0.5);\n"
"\t\t/* the edge leans toward the pointer */\n"
"\t\tline = mix(line, clamp(m.y, 0.15, 0.9), near * (0.35 - k * 0.08));\n"
"\t\tfloat d = fx.uv.y - line;\n"
"\t\t/* bright at its edge, fading slowly upward and quickly downward */\n"
"\t\tfloat curtain = d < 0.0 ? exp(d * (5.0 + k * 1.5)) : exp(-d * 40.0);\n"
"\t\t/* folds: vertical streaks that come and go */\n"
"\t\tfloat folds = 0.55 + 0.45 * raven_fbm(float2(x * 9.0 + k * 13.0, t * 2.0 + k));\n"
"\t\t/* color: the first at the edge, the second higher up */\n"
"\t\tfloat3 tone = mix(fx.color.rgb, fx.color2.rgb, clamp(-d * 3.0 + 0.15 * k, 0.0, 1.0));\n"
"\t\tlight += tone * curtain * folds * (0.55 - k * 0.12);\n"
"\t}\n"
"\t/* a few stars in the dark */\n"
"\tfloat2 cell = floor(fx.pixel / 3.0);\n"
"\tfloat star = step(0.9975, raven_hash(cell)) * (0.5 + 0.5 * sin(fx.time * 2.0 + raven_hash(cell + 7.0) * 30.0));\n"
"\tlight *= 1.0 + near * (0.9 + fx.press * 1.2);\n"
"\tfloat3 color = sky + light * intensity + float3(star * 0.6) * (1.0 - clamp(length(light) * 2.0, 0.0, 1.0));\n"
"\t/* (a little noise keeps the gradient smooth on 8-bit screens) */\n"
"\tcolor += (raven_hash(fx.pixel + fract(t) * 91.0) - 0.5) / 255.0;\n"
"\treturn float4(color, 1.0);\n"
"}\n";

/* shaders/effects/shimmer.metal */
static const char rvn_mtl_effect_shimmer_source[] =
"/* Shimmer: a band of light sweeping across, as on content that is loading.\n"
" * color: the surface; color2: the light (its alpha is its strength). params: speed, width (0..1), angle (degrees).\n"
" * The pointer: the light also gathers under it.\n"
" * (MSL twin of src/render/vulkan/shaders/effects/shimmer.frag) */\n"
"float4 raven_effect(RAVEN_EFFECT_ARGS) {\n"
"\tfloat speed = fx.params.x, width = clamp(fx.params.y, 0.02, 1.0), angle = fx.params.z * (RAVEN_PI / 180.0);\n"
"\tfloat2 direction = float2(cos(angle), sin(angle));\n"
"\t/* where the pixel is along the sweep, 0..1 across the whole rectangle whatever the angle */\n"
"\tfloat2 c = fx.pixel - fx.size * 0.5;\n"
"\tfloat reach = abs(direction.x) * fx.size.x * 0.5 + abs(direction.y) * fx.size.y * 0.5;\n"
"\tfloat along = dot(c, direction) / max(reach, 1.0) * 0.5 + 0.5;\n"
"\t/* the band goes from just before the start to just after the end, then waits a little */\n"
"\tfloat cycle = fract(fx.time * 0.45 * speed);\n"
"\tfloat position = mix(-width, 1.0 + width, clamp(cycle * 1.25, 0.0, 1.0));\n"
"\tfloat x = (along - position) / width;\n"
"\tfloat band = exp(-x * x * 4.0);\n"
"\tif (raven_has_pointer(fx)) {\n"
"\t\tfloat2 d = (fx.pixel - fx.pointer) / max(width * max(fx.size.x, fx.size.y), 1.0);\n"
"\t\tband = max(band, fx.hover * (0.7 + 0.3 * fx.press) * exp(-dot(d, d) * 2.0));\n"
"\t}\n"
"\treturn float4(mix(fx.color.rgb, fx.color2.rgb, band * fx.color2.a), fx.color.a);\n"
"}\n";

/* shaders/effects/neon.metal */
static const char rvn_mtl_effect_neon_source[] =
"/* Neon: an edge of light whose colors run around the shape.\n"
" * color, color2: the colors that chase each other. params: speed, width (pixels), glow (pixels).\n"
" * The pointer: the edge next to it burns brighter and wider; a press flashes the whole edge.\n"
" * (MSL twin of src/render/vulkan/shaders/effects/neon.frag) */\n"
"float4 raven_effect(RAVEN_EFFECT_ARGS) {\n"
"\tfloat speed = fx.params.x, width = max(fx.params.y, 0.5), glow = max(fx.params.z, 0.5);\n"
"\tfloat2 c = fx.pixel - fx.size * 0.5;\n"
"\t/* the angle around the middle, as a turn: 0..1 */\n"
"\tfloat turn = atan2(c.y * fx.size.x / max(fx.size.y, 1.0), c.x) / RAVEN_TAU + 0.5;\n"
"\tfloat phase = fract(turn - fx.time * 0.25 * speed);\n"
"\tfloat chase = 0.5 + 0.5 * cos(phase * RAVEN_TAU * 2.0);\n"
"\tfloat3 tone = mix(fx.color.rgb, fx.color2.rgb, chase);\n"
"\t/* the pointer heats the edge near it */\n"
"\tfloat near = 0.0;\n"
"\tif (raven_has_pointer(fx)) {\n"
"\t\tfloat reach = 0.3 * min(fx.size.x, fx.size.y) + 20.0;\n"
"\t\tnear = fx.hover * exp(-length(fx.pixel - fx.pointer) / reach);\n"
"\t\twidth *= 1.0 + near * 1.2;\n"
"\t\tglow *= 1.0 + near * 1.5 + fx.press * 0.8;\n"
"\t}\n"
"\t/* the line itself, then its glow toward the inside */\n"
"\tfloat inside = -fx.edge;\n"
"\tfloat line = 1.0 - smoothstep(width * 0.5, width * 0.5 + 1.0, abs(inside - width * 0.5));\n"
"\tfloat halo = exp(-max(inside - width, 0.0) / glow) * 0.55;\n"
"\t/* the brightest point of the chase is hotter */\n"
"\tfloat hot = pow(chase, 6.0) * 0.6 + near * 0.7 + fx.press * 0.35;\n"
"\tfloat3 color = tone * (line + halo) + float3(hot) * line;\n"
"\tfloat alpha = clamp(line + halo * 0.9, 0.0, 1.0) * max(fx.color.a, fx.color2.a);\n"
"\treturn float4(color / max(alpha, 1e-3), alpha);\n"
"}\n";

/* shaders/effects/ripple.metal */
static const char rvn_mtl_effect_ripple_source[] =
"/* Ripple: rings run over what is behind, like water. Needs the backdrop.\n"
" * color: tint (its alpha is its strength). params: speed, strength (pixels), density, center x (0..1).\n"
" * The pointer: the rings start from it, and a press makes them stronger.\n"
" * (MSL twin of src/render/vulkan/shaders/effects/ripple.frag) */\n"
"float4 raven_effect(RAVEN_EFFECT_ARGS) {\n"
"\tfloat speed = fx.params.x, strength = fx.params.y, density = max(fx.params.z, 0.1);\n"
"\tfloat2 center = float2(fx.params.w, 0.5) * fx.size;\n"
"\tif (raven_has_pointer(fx)) {\n"
"\t\tcenter = mix(center, fx.pointer, fx.hover);\n"
"\t\tstrength *= 1.0 + fx.press * 1.5;\n"
"\t}\n"
"\tfloat2 delta = fx.pixel - center;\n"
"\tfloat dist = length(delta);\n"
"\tfloat2 direction = dist > 0.0 ? delta / dist : float2(0.0);\n"
"\tfloat scale = min(fx.size.x, fx.size.y);\n"
"\tfloat phase = dist / scale * density * 6.0 - fx.time * speed * 4.0;\n"
"\t/* the rings fade toward the edge, and come in trains */\n"
"\tfloat fade = exp(-dist / scale * 1.2) * (0.6 + 0.4 * sin(phase * 0.25));\n"
"\tfloat wave = sin(phase) * fade;\n"
"\tfloat2 offset = direction * wave * strength;\n"
"\tfloat3 seen = raven_backdrop(fx.screen + offset).rgb;\n"
"\t/* the crests catch the light */\n"
"\tfloat crest = max(cos(phase), 0.0) * fade;\n"
"\t/* under the pointer the crests shine more, and the water glows a little */\n"
"\tfloat lit = 1.0 + fx.hover * 2.0 + fx.press * 2.0;\n"
"\tfloat3 color = mix(seen, fx.color.rgb, fx.color.a) + float3(crest * 0.08 * lit)\n"
"\t\t+ fx.color.rgb * fx.hover * 0.14 * exp(-dist / scale * 3.0);\n"
"\treturn float4(color, 1.0);\n"
"}\n";

/* shaders/effects/plasma.metal */
static const char rvn_mtl_effect_plasma_source[] =
"/* Plasma: bands of color that flow into each other.\n"
" * color, color2: the two ends of the palette. params: speed, scale, contrast.\n"
" * The pointer: the bands swirl around it, faster when it presses.\n"
" * (MSL twin of src/render/vulkan/shaders/effects/plasma.frag) */\n"
"float4 raven_effect(RAVEN_EFFECT_ARGS) {\n"
"\tfloat speed = fx.params.x, scale = max(fx.params.y, 0.05), contrast = max(fx.params.z, 0.1);\n"
"\tfloat aspect = fx.size.x / max(fx.size.y, 1.0);\n"
"\tfloat2 p = (fx.uv - 0.5) * float2(aspect, 1.0) * 5.0 * scale;\n"
"\tfloat t = fx.time * 0.6 * speed;\n"
"\tif (raven_has_pointer(fx)) {\n"
"\t\t/* a whirl centered on the pointer, strongest at its middle */\n"
"\t\tfloat2 m = (fx.pointer / max(fx.size, float2(1.0)) - 0.5) * float2(aspect, 1.0) * 5.0 * scale;\n"
"\t\tfloat2 r = p - m;\n"
"\t\tfloat turn = fx.hover * (1.6 + fx.press * 2.0) * exp(-dot(r, r) * 0.35);\n"
"\t\tfloat cs = cos(turn), sn = sin(turn);\n"
"\t\tp = m + float2x2(float2(cs, sn), float2(-sn, cs)) * r;\n"
"\t}\n"
"\tfloat v = sin(p.x + t);\n"
"\tv += sin((p.y + t) * 0.7);\n"
"\tv += sin((p.x + p.y + t) * 0.6);\n"
"\tv += sin(length(p + float2(sin(t * 0.33), cos(t * 0.5)) * 2.0) * 1.4 - t);\n"
"\tv = 0.5 + 0.5 * sin(v * 0.8 * contrast);\n"
"\t/* the middle of the palette goes through a third color: the two mixed and brightened */\n"
"\tfloat3 middle = clamp(mix(fx.color.rgb, fx.color2.rgb, 0.5) * 1.35 + 0.08, 0.0, 1.0);\n"
"\tfloat3 color = v < 0.5 ? mix(fx.color.rgb, middle, v * 2.0) : mix(middle, fx.color2.rgb, v * 2.0 - 1.0);\n"
"\treturn float4(color, mix(fx.color.a, fx.color2.a, v));\n"
"}\n";

/* shaders/effects/grain.metal */
static const char rvn_mtl_effect_grain_source[] =
"/* Grain: a gradient with the fine grain of film.\n"
" * color -> color2 along the angle. params: grain (0..1), angle (degrees).\n"
" * The pointer: a soft sheen follows it, as light on paper.\n"
" * (MSL twin of src/render/vulkan/shaders/effects/grain.frag) */\n"
"float4 raven_effect(RAVEN_EFFECT_ARGS) {\n"
"\tfloat grain = fx.params.x, angle = fx.params.y * (RAVEN_PI / 180.0);\n"
"\tfloat2 direction = float2(cos(angle), sin(angle));\n"
"\tfloat2 c = fx.pixel - fx.size * 0.5;\n"
"\tfloat reach = abs(direction.x) * fx.size.x * 0.5 + abs(direction.y) * fx.size.y * 0.5;\n"
"\tfloat t = clamp(dot(c, direction) / max(reach, 1.0) * 0.5 + 0.5, 0.0, 1.0);\n"
"\tt = t * t * (3.0 - 2.0 * t);\n"
"\tfloat4 color = mix(fx.color, fx.color2, t);\n"
"\t/* a new grain 24 times a second, like film */\n"
"\tfloat n = raven_hash(floor(fx.pixel) + floor(fx.time * 24.0) * float2(7.13, 3.71)) - 0.5;\n"
"\tcolor.rgb += n * grain * 0.18;\n"
"\tif (raven_has_pointer(fx)) {\n"
"\t\tfloat2 d = (fx.pixel - fx.pointer) / max(0.45 * max(fx.size.x, fx.size.y), 1.0);\n"
"\t\tcolor.rgb += (0.10 + 0.06 * fx.press) * fx.hover * exp(-dot(d, d) * 2.5);\n"
"\t}\n"
"\treturn color;\n"
"}\n";

/* shaders/effects/spotlight.metal */
static const char rvn_mtl_effect_spotlight_source[] =
"/* Spotlight: a soft light on a surface.\n"
" * color: the light; color2: the surface. params: x, y (0..1), radius (0..1 of the larger side).\n"
" * The pointer: the light goes where it is, and narrows and brightens when it presses.\n"
" * (MSL twin of src/render/vulkan/shaders/effects/spotlight.frag) */\n"
"float4 raven_effect(RAVEN_EFFECT_ARGS) {\n"
"\tfloat2 at = float2(fx.params.x, fx.params.y) * fx.size;\n"
"\tfloat radius = max(fx.params.z, 0.01) * max(fx.size.x, fx.size.y);\n"
"\tfloat boost = 1.0;\n"
"\tif (raven_has_pointer(fx)) {\n"
"\t\tat = mix(at, fx.pointer, fx.hover);\n"
"\t\tradius *= mix(1.0, 0.55, fx.hover) * (1.0 - 0.2 * fx.press);\n"
"\t\tboost = 1.0 + 0.5 * fx.hover + 0.5 * fx.press;\n"
"\t}\n"
"\tfloat d = length(fx.pixel - at) / radius;\n"
"\tfloat light = exp(-d * d * 2.2);\n"
"\tfloat3 color = fx.color2.rgb + fx.color.rgb * light * fx.color.a * boost;\n"
"\tcolor += (raven_hash(fx.pixel) - 0.5) / 255.0;\n"
"\treturn float4(color, fx.color2.a);\n"
"}\n";

/* shaders/effects/mesh.metal */
static const char rvn_mtl_effect_mesh_source[] =
"/* Mesh: four colors that blend across the surface and slowly move.\n"
" * color, color2 and two colors made from them. params: speed.\n"
" * The pointer: the colors are drawn toward it like a liquid, and a soft light follows it.\n"
" * (MSL twin of src/render/vulkan/shaders/effects/mesh.frag) */\n"
"float4 raven_effect(RAVEN_EFFECT_ARGS) {\n"
"\tfloat t = fx.time * 0.2 * fx.params.x;\n"
"\tfloat3 a = fx.color.rgb;\n"
"\tfloat3 b = fx.color2.rgb;\n"
"\tfloat3 c = clamp(mix(a, b, 0.5).gbr * 1.1, 0.0, 1.0);\n"
"\tfloat3 d = clamp(mix(a, b, 0.3) * 0.65 + 0.12, 0.0, 1.0);\n"
"\t/* the surface is warped slowly so that the corners wander */\n"
"\tfloat2 uv = fx.uv;\n"
"\tuv += 0.12 * float2(sin(uv.y * 3.0 + t * 2.0), cos(uv.x * 3.0 - t * 1.7));\n"
"\tuv += 0.06 * float2(raven_fbm(uv * 2.0 + t), raven_fbm(uv * 2.0 - t + 5.0)) - 0.03;\n"
"\t/* around the pointer the surface is pulled in: the colors gather there */\n"
"\tfloat glow = 0.0;\n"
"\tif (raven_has_pointer(fx)) {\n"
"\t\tfloat2 m = fx.pointer / max(fx.size, float2(1.0));\n"
"\t\tfloat2 to = uv - m;\n"
"\t\tfloat pull = exp(-dot(to, to) * 7.0) * fx.hover;\n"
"\t\tuv -= to * pull * (0.45 + 0.25 * fx.press);\n"
"\t\tglow = exp(-dot(fx.pixel - fx.pointer, fx.pixel - fx.pointer) / pow(0.35 * min(fx.size.x, fx.size.y), 2.0)) * fx.hover;\n"
"\t}\n"
"\tuv = clamp(uv, 0.0, 1.0);\n"
"\tfloat2 s = uv * uv * (3.0 - 2.0 * uv);\n"
"\tfloat3 color = mix(mix(a, c, s.x), mix(d, b, s.x), s.y);\n"
"\tcolor = mix(color, min(color * 1.25 + 0.1, 1.0), glow * 0.6);\n"
"\tcolor += (raven_hash(fx.pixel + t) - 0.5) / 255.0;\n"
"\treturn float4(color, mix(fx.color.a, fx.color2.a, uv.y));\n"
"}\n";

#define RVN_MTL_EFFECT_COUNT 8
/* in the order of REffect: aurora, shimmer, neon, ripple, plasma, grain, spotlight, mesh */
static const char* const rvn_mtl_effect_sources[RVN_MTL_EFFECT_COUNT] = {
	rvn_mtl_effect_aurora_source,
	rvn_mtl_effect_shimmer_source,
	rvn_mtl_effect_neon_source,
	rvn_mtl_effect_ripple_source,
	rvn_mtl_effect_plasma_source,
	rvn_mtl_effect_grain_source,
	rvn_mtl_effect_spotlight_source,
	rvn_mtl_effect_mesh_source
};

#endif
